module treeland_max_distance (\n    input clk,\n    input rst_n,\n    input start,\n    input [3:0] n,\n    input [3:0] k,\n    input [15:0] universities,\n    input [15:0] adj [0:15],\n    output reg [7:0] result,\n    output reg done\n);\n\n    // State declarations\n    localparam [2:0] IDLE         = 3'd0;\n    localparam [2:0] BUILD_TREE   = 3'd1;\n    localparam [2:0] CALC_SUBTREE = 3'd2;\n    localparam [2:0] CALC_DIST    = 3'd3;\n    localparam [2:0] FINISH       = 3'd4;\n    \n    reg [2:0] state;\n    reg [3:0] parent [0:15];\n    reg [3:0] subtree_count [0:15];\n    reg [7:0] total_dist;\n    \n    // BFS control\n    reg [3:0] current_node;\n    reg [3:0] bfs_queue [0:15];\n    reg [3:0] queue_head;\n    reg [3:0] queue_tail;\n    reg [15:0] visited;\n    \n    // Reverse processing\n    reg [3:0] reverse_counter;\n    \n    // Loop counters\n    integer i;\n    reg [3:0] j;\n    \n    // Maximum cycle counter\n    reg [7:0] cycle_count;\n    \n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 8'd0;\n            total_dist <= 8'd0;\n            cycle_count <= 8'd0;\n            \n            // Initialize all arrays\n            for (i = 0; i < 16; i = i + 1) begin\n                parent[i] <= 4'd15;  // Invalid value\n                subtree_count[i] <= 4'd0;\n                bfs_queue[i] <= 4'd0;\n            end\n            \n            queue_head <= 4'd0;\n            queue_tail <= 4'd0;\n            visited <= 16'd0;\n            reverse_counter <= 4'd0;\n            current_node <= 4'd0;\n            j <= 4'd0;\n        end else begin\n            cycle_count <= cycle_count + 8'd1;\n            \n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        // Initialize university markers\n                        for (i = 0; i < 16; i = i + 1) begin\n                            subtree_count[i] <= universities[i] ? 4'd1 : 4'd0;\n                        end\n                        \n                        // Clear BFS structures\n                        queue_head <= 4'd0;\n                        queue_tail <= 4'd1;\n                        bfs_queue[0] <= 4'd0;\n                        visited <= 16'd1;  // Node 0 visited\n                        parent[0] <= 4'd0;\n                        state <= BUILD_TREE;\n                    end\n                end\n                \n                BUILD_TREE: begin\n                    if (queue_head < queue_tail && cycle_count[0] == 1'b0) begin\n                        current_node <= bfs_queue[queue_head];\n                        queue_head <= queue_head + 4'd1;\n                        j <= 4'd0;\n                    end else if (j < n) begin\n                        if (adj[current_node][j] && !visited[j]) begin\n                            parent[j] <= current_node;\n                            visited[j] <= 1'b1;\n                            bfs_queue[queue_tail] <= j;\n                            queue_tail <= queue_tail + 4'd1;\n                        end\n                        j <= j + 4'd1;\n                    end else if (queue_head >= queue_tail) begin\n                        reverse_counter <= n - 4'd1;\n                        state <= CALC_SUBTREE;\n                    end\n                end\n                \n                CALC_SUBTREE: begin\n                    if (reverse_counter > 4'd0) begin\n                        if (parent[reverse_counter] != 4'd15) begin\n                            subtree_count[parent[reverse_counter]] <= subtree_count[parent[reverse_counter]] + subtree_count[reverse_counter];\n                        end\n                        reverse_counter <= reverse_counter - 4'd1;\n                    end else begin\n                        state <= CALC_DIST;\n                        reverse_counter <= 4'd1;  // Skip root\n                    end\n                end\n                \n                CALC_DIST: begin\n                    if (reverse_counter < n) begin\n                        if (subtree_count[reverse_counter] > 4'd0 && subtree_count[reverse_counter] < (k << 1)) begin\n                            if (subtree_count[reverse_counter] <= k) begin\n                                total_dist <= total_dist + {4'd0, subtree_count[reverse_counter]} * 8'd1;\n                            end else begin\n                                total_dist <= total_dist + (({4'd0, k} << 1) - {4'd0, subtree_count[reverse_counter]}) * 8'd1;\n                            end\n                        end\n                        reverse_counter <= reverse_counter + 4'd1;\n                    end else begin\n                        result <= total_dist;\n                        state <= FINISH;\n                    end\n                end\n                \n                FINISH: begin\n                    done <= 1'b1;\n                    if (!start) begin\n                        state <= IDLE;\n                    end\n                end\n                \n                default: state <= IDLE;\n            endcase\n            \n            // Timeout protection\n            if (cycle_count >= 8'd200) begin\n                state <= IDLE;\n                done <= 1'b1;\n            end\n        end\n    end\nendmodule